'use strict';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),modalContent=document.querySelector('#modal-content');
const types=['연차','조퇴','외출','병가','출장','공가'];const colors={'연차':['#e5edff','#3767ce'],'조퇴':['#fff0d9','#aa6a16'],'외출':['#e3f5ef','#238469'],'병가':['#fde9ec','#c65768'],'출장':['#eee8fd','#7d5cbc'],'공가':['#e1f1f9','#3483a7']};
let user=null,employees=[],events=[],view='calendar',selected='',month='',filter='',authMode='login',configured=true,summaryEmployee='',summaryDate='';const deadlineCache={};let auditFilters={action:'',from:'',to:'',actor_id:''};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seoulToday=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dateMonth=d=>d.slice(0,7), fmtDate=d=>`${Number(d.slice(5,7))}월 ${Number(d.slice(8,10))}일`,stamp=d=>`${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`;
const style=t=>`background:${colors[t][0]};color:${colors[t][1]}`;
async function api(url,opts={}){const r=await fetch(url,{headers:{'Content-Type':'application/json'},...opts});const j=await r.json();if(!r.ok){const e=new Error(j.error||j.warning||'오류가 발생했습니다.');e.warning=j.warning;throw e}return j}
function showDialog(html){modalContent.innerHTML=html;modal.showModal()}function closeDialog(){modal.close()}modal.addEventListener('click',e=>{if(e.target===modal)closeDialog()});
function login(){app.innerHTML=`<div class="auth-shell"><div class="card auth-card"><div class="brand"><span class="brand-mark">▦</span>근태 통합관리</div><h1>${authMode==='login'?'로그인':'회원가입 · 비밀번호 재설정'}</h1><p>${authMode==='login'?'사번과 비밀번호로 로그인해 주세요.':'사전 등록된 사번과 이름을 입력해 주세요.'}</p>${!configured?'<div class="notice">데이터베이스가 아직 연결되지 않았습니다. 화면 확인만 가능합니다.</div>':''}<form id="auth-form"><label class="field">사번<input name="employee_no" required autocomplete="username" placeholder="사번을 입력하세요"></label>${authMode==='signup'?'<label class="field">이름<input name="name" required autocomplete="name" placeholder="이름을 입력하세요"></label>':''}<label class="field">비밀번호<input type="password" name="password" required minlength="10" maxlength="128" autocomplete="${authMode==='login'?'current-password':'new-password'}" placeholder="${authMode==='login'?'비밀번호를 입력하세요':'10자 이상 입력하세요'}"></label>${authMode==='login'?'<label class="check"><input type="checkbox" name="remember"> 로그인 상태 유지</label>':''}<p class="error" id="auth-error"></p><button class="button primary wide" type="submit">${authMode==='login'?'로그인':'비밀번호 설정'}</button></form><div class="auth-links"><button class="link" id="switch-auth">${authMode==='login'?'처음이신가요? 회원가입 · 비밀번호 재설정':'로그인으로 돌아가기'}</button></div>${authMode==='signup'?'<div class="notice">비밀번호 분실 시 관리자에게 재설정 허용을 요청해 주세요.</div>':''}</div></div>`;document.querySelector('#switch-auth').onclick=()=>{authMode=authMode==='login'?'signup':'login';login()};document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),body=Object.fromEntries(f);body.remember=f.has('remember');try{await api(authMode==='login'?'/api/login':'/api/signup',{method:'POST',body:JSON.stringify(body)});if(authMode==='signup'){alert('비밀번호가 설정되었습니다. 로그인해 주세요.');authMode='login';login()}else{user=await api('/api/me');await refresh()}}catch(err){document.querySelector('#auth-error').textContent=err.message}}}
let dismissNavigation=null;
function shell(content){
 if(dismissNavigation)document.removeEventListener('click',dismissNavigation);
 const attendance=[['calendar','달력'],['registration','근태 등록'],['holidays','휴일근무'],['summary','직원별 현황']];
 const scheduling=[['workplaces','작업장 배치'],['support','날짜별 지원'],['weekly','주별 담당자'],['holiday-plan','휴일근무 배치'],['roster','월 근무표']];
 const management=[['employees','직원 관리'],['settings','마감일·휴일 설정'],['audit','변경 이력']];
 const groups=[['attendance','근태',attendance],...(user.role==='admin'?[['scheduling','근무표',scheduling],['management','관리',management]]:[])];
 const active=key=>key==='registration'?view.startsWith('registration'):view===key;
 const menu=groups.map(([id,label,items])=>`<div class="nav-group" data-nav-group="${id}"><button type="button" class="nav-group-toggle ${items.some(([key])=>active(key))?'active':''}" aria-expanded="false" aria-controls="nav-items-${id}">${label} <span aria-hidden="true">▾</span></button><div class="nav-mobile-label">${label}</div><div class="nav-group-items" id="nav-items-${id}">${items.map(([key,text])=>`<button type="button" data-view="${key}" class="${active(key)?'active':''}">${text}</button>`).join('')}</div></div>`).join('');
 app.innerHTML=`<header class="top"><div class="brand"><span class="brand-mark">▦</span>근태 통합관리</div><div class="top-right"><button type="button" class="menu-toggle" id="menu-toggle" aria-expanded="false" aria-controls="main-navigation">☰ 메뉴</button><nav class="nav" id="main-navigation" aria-label="주 메뉴"><div class="mobile-menu-heading"><strong>메뉴</strong><button type="button" id="menu-close" aria-label="메뉴 닫기">닫기 ×</button></div>${menu}</nav><span class="profile">${esc(user.name)}님</span><button id="logout" class="link">로그아웃</button></div></header><main class="wrap">${user.role==='admin'?'<div id="database-usage-alert" role="status" aria-live="polite"></div>':''}${content}</main>${view==='calendar'?'<div class="bottom-add"><button class="button primary" id="mobile-add">＋ 근태 등록</button></div>':''}`;
 const nav=document.querySelector('#main-navigation'),toggle=document.querySelector('#menu-toggle');
 const closeGroups=()=>nav.querySelectorAll('.nav-group').forEach(group=>{group.classList.remove('is-open');group.querySelector('.nav-group-toggle').setAttribute('aria-expanded','false')});
 const setMenuOpen=open=>{nav.classList.toggle('is-open',open);toggle.setAttribute('aria-expanded',String(open));if(!open)closeGroups()};
 toggle.onclick=()=>setMenuOpen(!nav.classList.contains('is-open'));document.querySelector('#menu-close').onclick=()=>{setMenuOpen(false);toggle.focus()};
 nav.querySelectorAll('.nav-group-toggle').forEach(button=>button.onclick=()=>{const group=button.closest('.nav-group'),open=!group.classList.contains('is-open');closeGroups();group.classList.toggle('is-open',open);button.setAttribute('aria-expanded',String(open))});
 nav.onkeydown=e=>{if(e.key==='Escape'){const open=nav.querySelector('.nav-group.is-open .nav-group-toggle');setMenuOpen(false);(open||toggle).focus()}};
 dismissNavigation=e=>{if(!nav.contains(e.target)&&!toggle.contains(e.target))setMenuOpen(false)};document.addEventListener('click',dismissNavigation);
 nav.querySelectorAll('[data-view]').forEach(b=>b.onclick=async()=>{setMenuOpen(false);if(b.dataset.view==='audit'){openAuditExport();return}if(b.dataset.view==='registration'&&view!=='registration'){const today=seoulToday();const [y,m]=today.slice(0,7).split('-').map(Number);month=stamp(new Date(Date.UTC(y,m,1))).slice(0,7);selected=month+'-01'}view=b.dataset.view;await refresh()});
 document.querySelector('#logout').onclick=async()=>{await api('/api/logout',{method:'POST'});user=null;login()};document.querySelector('#mobile-add')?.addEventListener('click',()=>editEvent());if(user.role==='admin')showDatabaseUsage();
}
// Admin-only, checked on site use; this does not delete data or send messages.
async function showDatabaseUsage(){
 const target=document.querySelector('#database-usage-alert');if(!target)return;
 try{
  const data=await api('/api/database-usage');if(!Number.isFinite(data.bytes)||data.bytes<0)throw Error('invalid usage');
  if(!target.isConnected||user?.role!=='admin')return;
  const used=data.bytes/1000000,limit=500;
  if(used>=limit*.8){target.className='database-usage-warning';target.textContent=`데이터베이스 용량 주의: 약 ${used.toFixed(1)} MB / 무료 한도 500 MB. 관리자에게 확인과 필요한 이력 정리를 권장합니다.`}
 }catch(e){if(target.isConnected&&user?.role==='admin'){target.className='database-usage-warning';target.textContent='데이터베이스 용량을 확인하지 못했습니다. Supabase 사용량을 확인해 주세요.'}}
}
async function refresh(){try{if(view==='calendar'){[events,employees,deadlineCache[month]]=await Promise.all([api('/api/attendance?month='+month),api('/api/employees'),api('/api/deadlines?month='+month)]);calendar()}else if(view==='registration')await registrationAttendancePage();else if(view==='registration-holiday')await holidayPage();else if(view==='registration-night')await registrationNightPage();else if(view==='registration-review')await registrationReviewPage();else if(view==='employees'){employees=await api('/api/employees');employeePage()}else if(view==='workplaces')await workplacePage();else if(view==='support')await workplaceSupportPage();else if(view==='weekly')await weeklyPage();else if(view==='holiday-plan')await holidayPlanPage();else if(view==='roster')await monthlyRosterPage();else if(view==='audit')await auditPage();else if(view==='holidays')await holidayPage();else if(view==='summary')await summaryPage();else if(view==='settings')await settingsPage()}catch(e){alert(e.message);if(e.message.includes('로그인')){user=null;login()}}}
function monthShift(offset){const [y,m]=month.split('-').map(Number);return stamp(new Date(Date.UTC(y,m-1+offset,1))).slice(0,7)}
function matchDay(d){return events.filter(x=>x.start_date<=d&&x.end_date>=d&&(!filter||String(x.employee_id)===filter))}
function duration(x){if(!x.start_time||!x.end_time)return '';let [a,b]=x.start_time.split(':').map(Number),[c,d]=x.end_time.split(':').map(Number);let n=c*60+d-a*60-b;return `${Math.floor(n/60)?Math.floor(n/60)+'시간 ':''}${n%60?n%60+'분':''}`.trim()}
function absenceCount(day){const grouped=new Map();for(const x of events.filter(x=>x.start_date<=day&&x.end_date>=day)){const key=String(x.employee_id);if(!x.start_time||!x.end_time){grouped.set(key,Infinity);continue}const [a,b]=x.start_time.split(':').map(Number),[c,d]=x.end_time.split(':').map(Number);grouped.set(key,(grouped.get(key)||0)+c*60+d-a*60-b)}return [...grouped.values()].filter(n=>n>=240).length}
function calendar(){const [y,m]=month.split('-').map(Number),first=new Date(Date.UTC(y,m-1,1)),offset=first.getUTCDay(),last=new Date(Date.UTC(y,m,0)).getUTCDate(),weeks=Math.ceil((offset+last)/7);let cells='';for(let i=0;i<weeks*7;i++){const dt=new Date(Date.UTC(y,m-1,1-offset+i)),d=stamp(dt),items=matchDay(d),outside=dateMonth(d)!==month;cells+=`<button class="day ${outside?'outside':''} ${d===selected?'selected':''} ${d===seoulToday()?'today':''} ${!outside&&absenceCount(d)>=7?'absence-alert':''}" data-date="${d}"><span class="day-number">${dt.getUTCDate()}</span>${items.map(x=>`<span class="event" data-type="${esc(x.type)}">${esc(x.name)} · ${esc(x.type)}</span>`).join('')}${items.length?`<span class="day-count">${items.length}건</span>`:''}</button>`}const items=matchDay(selected);const deadline=deadlineCache[month]?.attendance||null;const begin=deadlineCache[month]?.attendance_start||null;const closed=!begin||!deadline||seoulToday()<begin||seoulToday()>deadline;shell(`<div class="page-title"><div><h1>월별 근태 현황</h1><span class="muted">전체 직원의 근태 일정을 한눈에 확인하세요</span></div><button class="button primary desktop-add" id="add">＋ 근태 등록</button></div><div class="calendar-layout"><section class="card calendar-card"><div class="calendar-header"><div class="month-controls"><button class="arrow" id="prev" aria-label="이전 달">‹</button><h2>${y}년 ${m}월</h2><button class="arrow" id="next" aria-label="다음 달">›</button></div><button class="button small" id="today">오늘</button></div><div class="filters"><div class="legend">${types.map(t=>`<span><i class="dot" data-type="${esc(t)}"></i>${t}</span>`).join('')}</div>${user.role==='admin'?`<select id="filter" aria-label="직원별 조회"><option value="">전체 직원</option>${employees.map(e=>`<option value="${e.id}" ${filter===String(e.id)?'selected':''}>${esc(e.name)} (${esc(e.employee_no)})</option>`).join('')}</select>`:''}</div><div class="muted">${m}월 근태 ${!begin||!deadline?'등록 기간 미설정':`등록 기간 ${begin} ~ ${deadline}`} ${closed?'· 현재 직원 등록 불가':'· 현재 직원 등록 가능'} ${user.role==='admin'?'· 관리자는 마감 후에도 변경 가능':''}</div><div class="weekday">${['일','월','화','수','목','금','토'].map(s=>`<div>${s}</div>`).join('')}</div><div class="calendar">${cells}</div></section><aside class="card side"><div class="section-header"><h3>${fmtDate(selected)} 근태</h3><span class="count">${items.length}건</span></div>${items.length?items.map(x=>`<div class="event-row"><div><div class="event-name">${esc(x.name)}</div><div class="muted">${x.start_time?`${esc(x.start_time)} – ${esc(x.end_time)} · ${duration(x)}`:x.start_date===x.end_date?'하루':`${fmtDate(x.start_date)} – ${fmtDate(x.end_date)}`}</div></div><button class="badge" data-type="${esc(x.type)}" data-event="${x.id}">${esc(x.type)} ›</button></div>`).join(''):'<div class="empty">등록된 근태가 없습니다.</div>'}</aside></div>`);document.querySelector('#add')?.addEventListener('click',()=>editEvent());document.querySelector('#prev').onclick=async()=>{month=monthShift(-1);selected=month+'-01';await refresh()};document.querySelector('#next').onclick=async()=>{month=monthShift(1);selected=month+'-01';await refresh()};document.querySelector('#today').onclick=async()=>{selected=seoulToday();month=dateMonth(selected);await refresh()};document.querySelector('#filter')?.addEventListener('change',e=>{filter=e.target.value;calendar()});document.querySelectorAll('[data-date]').forEach(b=>b.onclick=async()=>{selected=b.dataset.date;if(dateMonth(selected)!==month){month=dateMonth(selected);await refresh()}else calendar()});document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>detail(events.find(x=>String(x.id)===b.dataset.event)))}
function annualDeadline(m){const [y,n]=m.split('-').map(Number),d=new Date(Date.UTC(y,n-1,0));d.setUTCDate(d.getUTCDate()-10);return stamp(d)}
function detail(x){const allowed=user.role==='admin'||String(user.id)===String(x.employee_id);showDialog(`<div class="dialog-inner"><div class="dialog-header"><h2>근태 상세</h2><button class="close" id="close">×</button></div><p><b>${esc(x.name)}</b> <span class="badge" data-type="${esc(x.type)}">${esc(x.type)}</span></p><p>${esc(x.start_date)}${x.start_date!==x.end_date?' ~ '+esc(x.end_date):''}</p>${x.start_time?`<p>${esc(x.start_time)} ~ ${esc(x.end_time)} (${duration(x)})</p>`:''}<p class="detail-note muted">${esc(x.note||'비고 없음')}</p><div class="modal-actions">${allowed?'<button class="button danger" id="delete">삭제</button><button class="button primary" id="edit">수정</button>':''}<button class="button" id="done">닫기</button></div></div>`);document.querySelector('#close').onclick=closeDialog;document.querySelector('#done').onclick=closeDialog;document.querySelector('#edit')?.addEventListener('click',()=>{closeDialog();editEvent(x)});document.querySelector('#delete')?.addEventListener('click',async()=>{if(!confirm('이 일정을 삭제하시겠습니까?'))return;try{await api('/api/attendance/'+x.id,{method:'DELETE'});closeDialog();await refresh()}catch(e){alert(e.message)}})}
function editEvent(item){const x=item||{type:'연차',start_date:selected,end_date:selected,employee_id:user.id};showDialog(`<div class="dialog-inner"><div class="dialog-header"><h2>${item?'근태 수정':'근태 등록'}</h2><button class="close" id="close">×</button></div><form id="event-form"><div class="form-grid">${user.role==='admin'?`<label class="field span2">대상 직원<select name="employee_id" required>${employees.filter(e=>e.active).map(e=>`<option value="${e.id}" ${String(e.id)===String(x.employee_id)?'selected':''}>${esc(e.name)} (${esc(e.employee_no)})</option>`).join('')}</select></label>`:''}<label class="field span2">근태 유형<select name="type" id="event-type">${types.map(t=>`<option ${t===x.type?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">시작 날짜<input type="date" name="start_date" value="${esc(x.start_date)}" required></label><label class="field" id="end-date-label">종료 날짜<input type="date" name="end_date" value="${esc(x.end_date)}" required></label><div id="time-fields" class="span2"></div><label class="field span2">비고 (선택)<textarea name="note" maxlength="1000">${esc(x.note||'')}</textarea></label></div><div class="muted" id="event-notice"></div><p class="error" id="event-error"></p><div class="modal-actions"><button type="button" class="button" id="cancel">취소</button><button class="button primary">${item?'저장':'등록'}</button></div></form></div>`);document.querySelector('#close').onclick=closeDialog;document.querySelector('#cancel').onclick=closeDialog;const form=document.querySelector('#event-form');const timeOptions=(value)=>'<option value="">선택</option>'+Array.from({length:48},(_,i)=>`${String(Math.floor(i/2)).padStart(2,'0')}:${i%2?'30':'00'}`).map(t=>`<option ${t===value?'selected':''}>${t}</option>`).join('');function typeChanged(){const type=form.elements.namedItem('type').value,single=['조퇴','외출'].includes(type),timed=single||['출장','병가','공가'].includes(type);document.querySelector('#end-date-label').style.display=single?'none':'';document.querySelector('#time-fields').innerHTML=timed?`${single?'':`<label class="field">등록 단위<select name="unit" id="event-unit"><option value="day" ${!x.start_time?'selected':''}>1일</option><option value="time" ${x.start_time?'selected':''}>시간</option></select></label>`}<div class="form-grid" id="timed-inputs"><label class="field">${type==='조퇴'?'조퇴 시작 시간':'시작 시간'}${['출장','병가','공가'].includes(type)?' (선택)':''}<select name="start_time">${timeOptions(x.start_time)}</select></label><label class="field">${type==='조퇴'?'정규 퇴근 시간':'종료 시간'}${['출장','병가','공가'].includes(type)?' (선택)':''}<select name="end_time">${timeOptions(x.end_time)}</select></label><div class="muted span2" id="calculated"></div></div>`:'';const unit=form.querySelector('#event-unit'),timeBox=form.querySelector('#timed-inputs');if(unit&&timeBox){const toggle=()=>{timeBox.hidden=unit.value!=='time';timeBox.querySelectorAll('select').forEach(el=>{el.disabled=unit.value!=='time';el.required=unit.value==='time'})};unit.addEventListener('change',toggle);toggle()}document.querySelector('#event-notice').textContent=type==='연차'?'근태 등록은 관리자 지정 월별 등록 시작일~마감일에만 가능합니다.':'';const calc=()=>{const a=form.start_time?.value,b=form.end_time?.value,output=document.querySelector('#calculated');if(output)output.textContent=a&&b&&a<b?'총 '+duration({start_time:a,end_time:b}):''};form.start_time?.addEventListener('change',calc);form.end_time?.addEventListener('change',calc);calc()}form.elements.namedItem('type').addEventListener('change',typeChanged);typeChanged();form.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));if(['조퇴','외출'].includes(data.type))data.end_date=data.start_date;const send=async()=>api(item?'/api/attendance/'+item.id:'/api/attendance',{method:item?'PUT':'POST',body:JSON.stringify(data)});try{try{await send()}catch(err){if(err.warning&&confirm(err.warning)){data.confirm_conflict=true;await send()}else throw err}closeDialog();await refresh()}catch(err){document.querySelector('#event-error').textContent=err.message}}}
function employeePage(){shell(`<div class="page-title"><div><h1>직원 관리</h1><span class="muted">직원 계정과 관리자 권한을 관리합니다.</span></div><button class="button primary" id="add-employee">＋ 직원 등록</button></div><label class="field employee-search">직원 이름 검색<input type="search" id="employee-search" placeholder="이름을 입력하세요" autocomplete="off"></label><div class="alert">회원가입과 비밀번호 재설정은 사번과 이름만 확인합니다. 다른 사람이 먼저 설정할 위험이 있습니다.</div><div class="card panel table-wrap"><table class="table" id="employee-list"><thead><tr><th>사번</th><th>이름</th><th>권한</th><th>계정</th><th>가입 상태</th><th>관리</th></tr></thead><tbody>${employees.map(e=>`<tr><td>${esc(e.employee_no)}</td><td>${esc(e.name)}</td><td>${e.role==='admin'?'관리자':'직원'}</td><td>${e.active?'활성':'비활성'}</td><td>${e.registered?'가입 완료':'미가입'}${e.reset_allowed?' · 재설정 허용':''}</td><td><div class="actions"><button class="button small" data-action="role" data-id="${e.id}">${e.role==='admin'?'직원으로 변경':'관리자 지정'}</button><button class="button small" data-action="active" data-id="${e.id}">${e.active?'비활성화':'활성화'}</button><button class="button small" data-action="reset" data-id="${e.id}">${e.reset_allowed?'재설정 취소':'재설정 허용'}</button></div></td></tr>`).join('')}</tbody></table></div>`);document.querySelector('#employee-search').oninput=e=>{const query=e.target.value.trim().toLocaleLowerCase('ko-KR');document.querySelectorAll('#employee-list tbody tr').forEach(row=>{row.hidden=!row.cells[1].textContent.toLocaleLowerCase('ko-KR').includes(query)})};document.querySelector('#add-employee').onclick=()=>{showDialog(`<div class="dialog-inner"><div class="dialog-header"><h2>직원 등록</h2><button class="close" id="close">×</button></div><form id="employee-form"><label class="field">사번<input name="employee_no" required></label><label class="field">이름<input name="name" required></label><label class="field">권한<select name="role"><option value="employee">직원</option><option value="admin">관리자</option></select></label><p class="error" id="employee-error"></p><div class="modal-actions"><button class="button primary">등록</button></div></form></div>`);document.querySelector('#close').onclick=closeDialog;document.querySelector('#employee-form').onsubmit=async ev=>{ev.preventDefault();try{await api('/api/employees',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(ev.target)))});closeDialog();await refresh()}catch(err){document.querySelector('#employee-error').textContent=err.message}}};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const e=employees.find(x=>String(x.id)===b.dataset.id),action=b.dataset.action;const body=action==='role'?{role:e.role==='admin'?'employee':'admin'}:action==='active'?{active:!e.active}:{reset_allowed:!e.reset_allowed};if(!confirm(`${e.name}님의 설정을 변경하시겠습니까?`))return;try{await api('/api/employees/'+e.id,{method:'PATCH',body:JSON.stringify(body)});await refresh()}catch(err){alert(err.message)}})}
