let weeklySelection={type:'하림:조출',week:''};
function weeklyOverrideMarkup(data,slot){
 const items=data.overrides||[],days=Math.round((Date.parse(data.end+'T00:00:00Z')-Date.parse(data.week+'T00:00:00Z'))/86400000)+1;
 return `<details class="weekly-overrides"><summary>담당 ${slot} 날짜별 대체</summary>${Array.from({length:days},(_,i)=>{const day=stamp(new Date(Date.parse(data.week+'T00:00:00Z')+i*86400000)),item=items.find(x=>Number(x.slot)===slot&&x.work_date===day),value=!item?'default':item.employee_id==null?'empty':String(item.employee_id),current=data.candidates.find(x=>String(x.id)===value);return `<label class="field">${esc(day)}<select class="weekly-override" data-slot="${slot}" data-day="${day}"><option value="default" ${value==='default'?'selected':''}>주 담당자</option><option value="empty" ${value==='empty'?'selected':''}>미배치</option>${current?.reasons.length?`<option value="${esc(current.id)}" selected>${esc(current.name)} · 확인 필요</option>`:''}${data.candidates.filter(x=>!x.reasons.length).map(x=>`<option value="${esc(x.id)}" ${value===String(x.id)?'selected':''}>${esc(x.name)}${x.attendance?' · 주간 근태 있음':''}</option>`).join('')}</select></label>`}).join('')}</details>`;
}
