 const monthStart=month+'-01',monthEnd=stamp(new Date(Date.UTC(yy,mm,0)));const daysBetween=(start,end)=>Math.floor((Date.parse(end+'T00:00:00Z')-Date.parse(start+'T00:00:00Z'))/86400000)+1;
